using System.Numerics;
using System.Text.Json;
namespace BobbyBoi;
static class ChaosTests {
 public static void Run(){Directory.CreateDirectory("artifacts");using(var gallery=new Bitmap(1280,690)){using var g=Graphics.FromImage(gallery);g.Clear(Color.FromArgb(25,28,32));int i=0;foreach(string name in ChaosAssets.Names){var p=new Vector2(160+i%4*320,195+i/4*230);ChaosAssets.Draw(g,name,p,3.5f,.3f);PixelText.Draw(g,name,(int)p.X-70,(int)p.Y+12,Color.Goldenrod,1);i++;}gallery.Save("artifacts/chaos-assets.png");}
  using(var b=new Bitmap(780,190)){using var g=Graphics.FromImage(b);g.Clear(Color.FromArgb(49,54,57));string[] text=["i have emotional support cobblestone","the nether has taxes","my bail is 64 emeralds"];for(int i=0;i<3;i++){using var bubble=new MinecraftBubble();var save=g.Save();g.TranslateTransform(i*260,10);bubble.Draw(g,text[i],3,260,new[]{Color.FromArgb(132,185,100),Color.FromArgb(184,116,245),Color.Goldenrod}[i]);g.Restore(save);}b.Save("artifacts/speech-bubbles.png");}
  using(var walk=new Bitmap(960,240)){using var g=Graphics.FromImage(walk);g.Clear(Color.FromArgb(25,28,32));for(int i=0;i<6;i++)ChaosAssets.Draw(g,"golem",new(80+i*160,205),4,i<3?-.85f:.85f,new[]{0,.314f,.942f}[i%3],true);walk.Save("artifacts/golem-walk.png");}
  using var pet=new Pet(true,true);pet.VerifyChaos();
 }
}
sealed partial class Pet {
 public void VerifyChaos(){worldTesting=true;data.World=new(){Automatic=false};data.Volume=0;data.NaturalMobs=false;data.Expeditions.Enabled=false;wolf=null;mobs.Clear();clones.Clear();energy=90;hunger=80;curiosity=90;mischief=60;data.Items=SaveData.Names.ToDictionary(n=>n,_=>0);data.Items["Emerald"]=66;var report=new List<string>();
  void Start(WorldEventKind kind,int result=2){world.Clear();CancelWorld();health=20;respawnTime=0;throwVx=vy=0;action=Act.Idle;forcedChaosResult=result;world.Queue(kind);UpdateWorld(.1f);if(world.Active?.Spec.Kind!=kind)throw new Exception("Failed to start "+kind);}
  void Finish(){for(int i=0;i<450&&world.Busy;i++)UpdateWorld(.1f);if(world.Busy||actorInside||characterWorldScale!=1)throw new Exception("Expansion did not recover after "+world.Active?.Spec.Kind);}
  void Followup(WorldEventKind kind){UpdateWorld(.1f);if(world.Active?.Spec.Kind!=kind)throw new Exception("Missing connected event: "+kind);Finish();}
  try{
   foreach(var kind in Enum.GetValues<WorldEventKind>().Where(k=>k>=WorldEventKind.Prison)){if(kind==WorldEventKind.AdoptCreeper)data.World.PetCreeper=false;Start(kind);for(int i=0;i<(kind==WorldEventKind.Prison?110:kind==WorldEventKind.Ufo?50:40);i++)UpdateWorld(.1f);var visuals=ExpansionVisuals().ToList();if(visuals.Count==0)throw new Exception("No animated visual for "+kind);using(var snap=WorldCanvas.Snapshot(visuals,new((int)chaosAnchor.X-280,(int)chaosAnchor.Y-300,600,350)))snap.Save("artifacts/chaos-"+kind+".png");Finish();report.Add("PASS: "+kind+" starts, animates, completes, cleans up visibility and scale.");}
   data.World.PetCreeper=false;Start(WorldEventKind.Casino,0);Finish();if(data.Items["Emerald"]!=2)throw new Exception("Casino balance or negative inventory");Followup(WorldEventKind.Prison);report.Add("PASS: casino loss -> prison; fake emeralds only; balances never negative.");
   Start(WorldEventKind.Cave,0);Finish();Followup(WorldEventKind.Herobrine);report.Add("PASS: cave -> Herobrine sighting.");
   Start(WorldEventKind.Portal,0);Finish();Followup(WorldEventKind.AdoptCreeper);if(!data.World.PetCreeper||mobs.Count!=0)throw new Exception("Pet creeper registered as hostile");int hp=health;UpdateExpansionCompanion(30);if(health!=hp)throw new Exception("Friendly confetti damaged pet");report.Add("PASS: portal -> persistent friendly creeper; confetti has no damage.");
   Start(WorldEventKind.Ufo);Finish();Followup(WorldEventKind.YouTube);if(data.World.Subscribers<3)throw new Exception("Video counter");report.Add("PASS: UFO -> offline tiny video and subscriber counter; no online actions.");
   Start(WorldEventKind.FakeUpdate);for(int i=0;i<60;i++)UpdateWorld(.1f);if(world.Active?.Spec.Kind!=WorldEventKind.FakeUpdate||bubble!="99 percent. zero hope")throw new Exception("99 percent hold missing");Finish();report.Add("PASS: fake update holds at 99%, frustration, completion loot.");
   Start(WorldEventKind.Earthquake,0);if(WorldShake==Vector2.Zero)throw new Exception("Quake shake missing");Finish();Followup(WorldEventKind.Cave);report.Add("PASS: local world-only quake/fall -> cave.");
   foreach(var kind in new[]{WorldEventKind.Ufo,WorldEventKind.Portal,WorldEventKind.Prison,WorldEventKind.Cave}){Start(kind);for(int i=0;i<75&&world.Busy;i++)UpdateWorld(.1f);CancelWorld();if(actorInside||characterWorldScale!=1)throw new Exception("Cancelled disappearance: "+kind);}report.Add("PASS: dragging/cancellation recovery from portals, cave, jail and UFO.");
   var serialized=JsonSerializer.Serialize(data.World);var restored=JsonSerializer.Deserialize<WorldState>(serialized)!;if(!restored.PetCreeper||restored.LastEvents.Count<8||restored.Achievements.Count<10)throw new Exception("Expansion persistence");data.World.Creepy=false;world.Clear();world.Queue(WorldEventKind.Herobrine);if(world.Tick(.1f,data.World,true,false,_=>true)!=null)throw new Exception("Disabled sightings started");report.Add("PASS: achievements, companions, cooldown timestamps persist; creepy opt-out works.");
   var inventory=menu.Items.OfType<ToolStripMenuItem>().Single(i=>i.Text=="Inventory");menu.Show(new Point(80,80));inventory.ShowDropDown();if(!inventory.DropDown.Visible)throw new Exception("Submenu fixture not visible");if(inventory.DropDownItems.Cast<ToolStripItem>().Any(i=>i.Text!.Contains('\uFFFD')))throw new Exception("Inventory broken glyph");menu.DismissIfOutside(new(menu.Right+100,menu.Bottom+100));Application.DoEvents();if(menu.Visible||inventory.DropDown.Visible)throw new Exception("Orphaned submenu after outside click");report.Add("PASS: ASCII inventory x counts and submenu dismissal with root menu.");
   File.WriteAllLines("artifacts/chaos-tests.txt",report);
  }catch(Exception e){File.WriteAllLines("artifacts/chaos-tests.txt",report.Append(e.ToString()));throw;}finally{timer.Stop();tray.Dispose();menu.Dispose();mobs.Dispose();worldCanvas.Dispose();}
 }
}
